      background: linear-gradient(135deg, var(--accent) 0%, #9dd0ff 100%);
      color: #06111d;
      font-weight: 700;
    }

    .button-secondary {
      border-color: var(--line-strong);
      background: rgba(255, 255, 255, 0.02);
    }

    .hero-stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 14px;
    }

    .stat {
      padding: 18px;
      border-radius: var(--radius-md);
      border: 1px solid rgba(255, 255, 255, 0.08);
      background: rgba(6, 10, 16, 0.45);
    }

    .stat strong {
      display: block;
      font-size: 1.35rem;
      margin-bottom: 6px;
    }

    .stat span {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .promo-card {
      position: relative;
      overflow: hidden;
      padding: 30px;
      display: grid;
      grid-template-rows: auto auto 1fr auto;
      gap: 18px;
    }

    .product-orbit {
      aspect-ratio: 1 / 1;
      border-radius: 24px;
      position: relative;
      overflow: hidden;
      background:
        radial-gradient(circle at 50% 50%, rgba(138, 180, 255, 0.22), transparent 42%),
        linear-gradient(135deg, rgba(16, 23, 34, 0.95), rgba(10, 15, 22, 0.65));
      border: 1px solid rgba(255, 255, 255, 0.08);
      display: grid;
      place-items: center;
    }

    .product-orbit::before,
    .product-orbit::after {
      content: "";
      position: absolute;
      border-radius: 50%;
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .product-orbit::before {
      inset: 18%;
    }

    .product-orbit::after {
      inset: 6%;
    }

    .device {
      width: 52%;
      aspect-ratio: 0.9 / 1.1;
      border-radius: 30px;
      background:
        linear-gradient(160deg, rgba(255, 255, 255, 0.75), rgba(178, 186, 205, 0.18) 30%, rgba(52, 70, 102, 0.85) 88%),
        linear-gradient(160deg, rgba(12, 19, 28, 0.8), rgba(17, 21, 29, 0.95));
      box-shadow:
        inset 0 0 0 1px rgba(255, 255, 255, 0.2),
        0 30px 50px rgba(0, 0, 0, 0.35);
      position: relative;
    }

    .device::before {
      content: "";
      position: absolute;
      inset: 10px;
      border-radius: 22px;
      background: linear-gradient(180deg, rgba(7, 9, 14, 0.35), rgba(7, 9, 14, 0.8));
    }

    .device::after {
      content: "";
      position: absolute;
      width: 22%;
      height: 22%;
      right: 18px;
      top: 18px;
      border-radius: 50%;
      background: radial-gradient(circle at 35% 35%, rgba(255, 255, 255, 0.7), rgba(170, 180, 205, 0.12));
      box-shadow: 0 0 0 8px rgba(255, 255, 255, 0.06);
    }

    .promo-meta {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      align-items: center;
      color: var(--muted);
      font-size: 0.94rem;
    }

    .section {
      padding: 26px 0;
    }

    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 20px;
      margin-bottom: 20px;
      flex-wrap: wrap;
    }

    .section-header p {
      color: var(--muted);
      max-width: 62ch;
      line-height: 1.65;
    }

    .kicker {
      color: var(--accent-strong);
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.78rem;
      margin-bottom: 8px;
    }

    .filter-bar {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      margin-bottom: 18px;
    }

    .chip {
      min-height: 40px;
      padding: 0 14px;
      border-radius: var(--radius-sm);
      border: 1px solid var(--line);
      background: rgba(255, 255, 255, 0.02);
      color: var(--muted);
      transition: border-color 180ms ease, color 180ms ease, background 180ms ease;
    }

    .chip[aria-pressed="true"] {
      color: var(--text);
      border-color: rgba(138, 180, 255, 0.4);
      background: rgba(138, 180, 255, 0.12);
    }

    .product-grid,
    .story-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
    }

    .card {
      padding: 22px;
      display: grid;
      gap: 16px;
      min-height: 100%;
    }

    .product-art {
      min-height: 220px;
      border-radius: 22px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      position: relative;
      overflow: hidden;
      background: linear-gradient(180deg, rgba(18, 24, 34, 0.8), rgba(10, 14, 20, 1));
    }

    .product-art::before,
    .product-art::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      filter: blur(2px);
    }

    .product-art::before {
      width: 140px;
      height: 140px;
      background: rgba(138, 180, 255, 0.22);
      top: 22px;
      right: 14px;
    }

    .product-art::after {
      width: 90px;
      height: 90px;
      background: rgba(201, 166, 107, 0.22);
      bottom: 18px;
      left: 20px;
    }

    .product-shape {
      position: absolute;
      inset: 20px;
      border-radius: 28px;
      background:
        linear-gradient(150deg, rgba(255, 255, 255, 0.82), rgba(175, 187, 208, 0.18) 28%, rgba(60, 76, 105, 0.95) 82%),
        linear-gradient(150deg, rgba(12, 20, 29, 0.8), rgba(18, 22, 30, 0.92));
      box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.22);
    }

    .product-shape.round {
      border-radius: 50%;
      inset: 30px;
    }

    .product-shape.tall {
      inset-inline: 58px;
    }

    .card-topline,
    .story-meta {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      align-items: center;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      width: fit-content;
      padding: 6px 10px;
      border-radius: var(--radius-sm);
      background: rgba(131, 230, 177, 0.12);
      color: var(--success);
      border: 1px solid rgba(131, 230, 177, 0.2);
      font-size: 0.86rem;
    }

    .price-row {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 12px;
      flex-wrap: wrap;
    }

    .price {
      font-size: 1.5rem;
      font-weight: 700;
    }

    .subtle {
      color: var(--muted);
      line-height: 1.65;
    }

    .deal-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.15fr) minmax(280px, 0.85fr);
      gap: 18px;
    }

    .deal-feature,
    .deal-side {
      padding: 26px;
      border-radius: var(--radius-xl);
      border: 1px solid var(--line);
      background: var(--panel);
      box-shadow: var(--shadow);
    }

    .deal-feature {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(220px, 0.9fr);
      gap: 24px;
      align-items: center;
    }

    .timer {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 10px;
      margin-top: 22px;
    }

    .timer-block {
      padding: 14px;
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.08);
      text-align: center;
    }

    .timer-block strong {
      display: block;
      font-size: 1.4rem;
      margin-bottom: 5px;
    }

    .deal-visual {
      min-height: 280px;
      border-radius: 24px;
      position: relative;
      overflow: hidden;
      background:
        radial-gradient(circle at 30% 30%, rgba(138, 180, 255, 0.25), transparent 22%),
        radial-gradient(circle at 78% 70%, rgba(201, 166, 107, 0.24), transparent 24%),
        linear-gradient(145deg, #0d1520, #111827);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .deal-visual::before,
    .deal-visual::after {
      content: "";
      position: absolute;
      background: linear-gradient(145deg, rgba(255, 255, 255, 0.76), rgba(169, 180, 200, 0.15) 30%, rgba(53, 68, 92, 0.92) 84%);
      box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.18);
    }

    .deal-visual::before {
      width: 46%;
      height: 70%;
      left: 12%;
      top: 16%;
      border-radius: 34px;
      transform: rotate(-8deg);
    }

    .deal-visual::after {
      width: 30%;
      height: 48%;
      right: 12%;
      bottom: 12%;
      border-radius: 24px;
      transform: rotate(10deg);
    }

    .deal-side {
      display: grid;
      gap: 16px;
      align-content: start;
    }

    .deal-item {
      display: grid;
      gap: 6px;
      padding: 16px;
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .deal-item strong {
      font-size: 1.05rem;
    }

    .progress {
      height: 8px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.07);
      overflow: hidden;
      margin-top: 4px;
    }

    .progress > span {
      display: block;
      height: 100%;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--accent), var(--accent-strong));
    }

    .story-card {
      position: relative;
      padding: 24px;
      overflow: hidden;
      display: grid;
      gap: 16px;
    }

    .story-cover {
      min-height: 210px;
      border-radius: 22px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      background:
        linear-gradient(160deg, rgba(10, 13, 18, 0.08), rgba(10, 13, 18, 0.75)),
        linear-gradient(135deg, rgba(138, 180, 255, 0.2), rgba(201, 166, 107, 0.18)),
        linear-gradient(180deg, #111b29, #0a0f16);
      position: relative;
      overflow: hidden;
    }

    .story-cover::before,
    .story-cover::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.14);
    }

    .story-cover::before {
      width: 65%;
      height: 18px;
      left: 18px;
      bottom: 52px;
    }

    .story-cover::after {
      width: 42%;
      height: 18px;
      left: 18px;
      bottom: 22px;
    }

    .newsletter {
      margin: 30px 0 44px;
      padding: 28px;
      border-radius: var(--radius-xl);
      border: 1px solid var(--line);
      background:
        radial-gradient(circle at 10% 10%, rgba(138, 180, 255, 0.16), transparent 22%),
        linear-gradient(135deg, rgba(17, 23, 35, 0.98), rgba(11, 15, 22, 0.94));
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 20px;
      align-items: center;
      box-shadow: var(--shadow);
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    .newsletter input {
      min-width: min(100%, 280px);
      min-height: 48px;
      padding: 0 16px;
      border-radius: var(--radius-sm);
      border: 1px solid var(--line-strong);
      background: rgba(255, 255, 255, 0.04);
      color: var(--text);
    }

    .newsletter input::placeholder {
      color: #8d99aa;
    }

    footer {
      padding: 0 0 36px;
      color: var(--muted);
    }

    .footer-row {
      display: flex;
      justify-content: space-between;
      gap: 16px;
      flex-wrap: wrap;
      border-top: 1px solid rgba(255, 255, 255, 0.08);
      padding-top: 22px;
    }

    .product-card[hidden] {
      display: none;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 1024px) {
      .hero-grid,
      .deal-grid,
      .deal-feature,
      .newsletter,
      .product-grid,
      .story-grid {
        grid-template-columns: 1fr;
      }

      .promo-card {
        min-height: 100%;
      }
    }

    @media (max-width: 720px) {
      .site-header .shell,
      .section-header,
      .footer-row {
        align-items: start;
      }

      .hero-panel,
      .promo-card,
      .deal-feature,
      .deal-side,
      .newsletter,
      .card,
      .story-card {
        padding: 22px;
      }

      .hero-stats,
      .timer {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      h1 {
        line-height: 1;
      }
    }
  </style>
</head>
